    py_code = f'''import json

def transform(grid):
    """Transform rule: Connected regions of 1s are filled with their seed value."""

    n_rows = len(grid)
    n_cols = len(grid[0]) if n_rows > 0 else 0

    # Find all seeds and their values
    seeds = {}
    for r in range(n_rows):
        for c in range(n_cols):
            val = grid[r][c]
            if val not in [0, 1]:
                seeds[(r, c)] = val

    if not seeds:
        # No seeds, return copy
        return [row[:] for row in grid]

    result = [[0] * n_cols for _ in range(n_rows)]
    visited = set()

    # Find connected regions
    for r in range(n_rows):
        for c in range(n_cols):
            if grid[r][c] != 0 and (r, c) not in visited:
                # BFS to find all non-zero cells in this region
                region = []
                stack = [(r, c)]
                while stack:
                    cr, cc = stack.pop()
                    if (cr, cc) in visited or grid[cr][cc] == 0 or (cr, cc) in region:
                        continue
                    visited.add((cr, cc))
                    region.append((cr, cc))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < n_rows and 0 <= nc < n_cols:
                            if grid[nr][nc] != 0 and (nr, nc) not in visited and (nr, nc) not in region:
                                stack.append((nr, nc))

                # Find seed values in this region
                seed_vals = [grid[cr][cc] for cr, cc in region]
                non_seed = [v for v in seed_vals if v not in [0, 1]]

                if len(non_seed) == 1 and len(set(non_seed)) == 1:
                    # Region has exactly one seed value
                    seed_val = non_seed[0]
                else:
                    seed_val = None

                # Fill region
                for cr, cc in region:
                    if (cr, cc) in seeds:
                        result[cr][cc] = seeds[(cr, cc)]
                    elif grid[cr][cc] == 1:
                        if seed_val is not None:
                            result[cr][cc] = seed_val
                    else:
                        result[cr][cc] = grid[cr][cc]

    return result
